import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.BWixA7XM.js";const u=JSON.parse('{"title":"认识 FrameAnalysis 目录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dump/anatomy.md","filePath":"guide/dump/anatomy.md","lastUpdated":1795572648000}'),p={name:"guide/dump/anatomy.md"};function d(l,a,r,i,c,o){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="认识-frameanalysis-目录" tabindex="-1">认识 FrameAnalysis 目录 <a class="header-anchor" href="#认识-frameanalysis-目录" aria-label="Permalink to &quot;认识 FrameAnalysis 目录&quot;">​</a></h1><p>按 F8 之后，3DMigoto 会在游戏目录（或 <code>d3dx.ini</code> 指定的位置）生成一个 <code>FrameAnalysis-&lt;日期&gt;-&lt;时间&gt;</code> 目录。打开它，第一眼通常是懵的：几千个文件，名字全是一串哈希。</p><p>这一节把它彻底讲明白。</p><h2 id="两种目录形态" tabindex="-1">两种目录形态 <a class="header-anchor" href="#两种目录形态" aria-label="Permalink to &quot;两种目录形态&quot;">​</a></h2><p>不同版本的 3DMigoto / 不同 <code>d3dx.ini</code> 配置会产出两种形态。</p><h3 id="形态一-平铺" tabindex="-1">形态一：平铺 <a class="header-anchor" href="#形态一-平铺" aria-label="Permalink to &quot;形态一：平铺&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FrameAnalysis-2026-11-17-215525\\</span></span>
<span class="line"><span>├── 000001-ib=00000000-vs=653c63ba4a73ca8b-ps=...-vs-cb4=ad3c80a5.buf</span></span>
<span class="line"><span>├── 000038-ib=7ad7e69e-vs=1844db3b...-ps=f5aa22fa....buf</span></span>
<span class="line"><span>├── 000038-ib=7ad7e69e-vs=1844db3b...-ps=f5aa22fa....txt</span></span>
<span class="line"><span>├── 000041-ps-t0=10c4fa9f.dds</span></span>
<span class="line"><span>└── log.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>所有 <code>.buf</code> / <code>.txt</code> / <code>.dds</code> 都直接躺在根目录。文件本身就是数据。</p><h3 id="形态二-deduped-去重" tabindex="-1">形态二：deduped（去重） <a class="header-anchor" href="#形态二-deduped-去重" aria-label="Permalink to &quot;形态二：deduped（去重）&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FrameAnalysis-2026-11-17-215525\\</span></span>
<span class="line"><span>├── 000038-ib=7ad7e69e-vs=...-ps=....buf.lnk   ← 快捷方式，1.5 KB</span></span>
<span class="line"><span>├── 000038-ib=7ad7e69e-vs=...-ps=....txt.lnk</span></span>
<span class="line"><span>├── log.txt                                      ← 4.8 MB</span></span>
<span class="line"><span>└── deduped\\                                     ← 真正的数据</span></span>
<span class="line"><span>    ├── 9c2ac78e.buf                            ← 名字是内容哈希</span></span>
<span class="line"><span>    ├── 9c2ac78e-vb0-layout=5bfd1268-topology=trianglelist-stride=40-count=18531.txt</span></span>
<span class="line"><span>    ├── 7ad7e69e.buf</span></span>
<span class="line"><span>    └── 10c4fa9f-BC7_UNORM_SRGB.dds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>根目录全是 <code>.lnk</code>（Windows 快捷方式），真实数据在 <code>deduped\\</code> 里。</p><div class="warning custom-block"><p class="custom-block-title">deduped 的核心陷阱</p><p><code>deduped\\</code> 里 <code>.buf</code> 的文件名是<strong>内容哈希</strong>，不是资源哈希。</p><ul><li>根目录的逻辑名告诉你：<code>000038</code> 这个 draw 用了 <code>ib=7ad7e69e</code>、<code>vb0=1844db3b</code></li><li>但 <code>deduped\\</code> 里可能根本没有 <code>1844db3b.buf</code> —— 真实文件叫 <code>9c2ac78e.buf</code></li></ul><p><strong>「资源哈希 → 真实文件」的映射只存在于 <code>log.txt</code> 里。</strong> 这就是为什么所有脚本第一件事都是解析 log。</p></div><h2 id="文件命名规则" tabindex="-1">文件命名规则 <a class="header-anchor" href="#文件命名规则" aria-label="Permalink to &quot;文件命名规则&quot;">​</a></h2><h3 id="drawcall-资源文件" tabindex="-1">DrawCall 资源文件 <a class="header-anchor" href="#drawcall-资源文件" aria-label="Permalink to &quot;DrawCall 资源文件&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>000038-ib=7ad7e69e-vs=1844db3b8cd1b6ff-ps=f5aa22fa2bba0707.buf</span></span>
<span class="line"><span>└──┬──┘ └────┬────┘ └───────┬───────┘ └───────┬───────┘</span></span>
<span class="line"><span>   │         │              │                  │</span></span>
<span class="line"><span>   │         │              │                  └─ Pixel Shader 哈希（16 hex）</span></span>
<span class="line"><span>   │         │              └─ Vertex Shader 哈希（16 hex）</span></span>
<span class="line"><span>   │         └─ Index Buffer 哈希（8 hex）</span></span>
<span class="line"><span>   └─ drawcall 序号（6 位十进制，本次帧里的调用顺序）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>各部分含义：</p><table tabindex="0"><thead><tr><th>部分</th><th>长度</th><th>含义</th><th>能用来做什么</th></tr></thead><tbody><tr><td><code>000038</code></td><td>6 位十进制</td><td>drawcall 序号</td><td>去 log 里找这次调用的参数（索引数、起止位置）</td></tr><tr><td><code>ib=7ad7e69e</code></td><td>8 hex</td><td>索引缓冲哈希</td><td><strong>这是「某个模型」的 ID</strong>，同一 IB 的所有 draw 共享它</td></tr><tr><td><code>vs=...</code></td><td>16 hex</td><td>顶点着色器哈希</td><td>同一套渲染流程的 draw 共享</td></tr><tr><td><code>ps=...</code></td><td>16 hex</td><td>像素着色器哈希</td><td>同一套材质/效果的 draw 共享</td></tr></tbody></table><p><strong>重点</strong>：<code>ib=</code> 后面的 8 位哈希是你要找的东西。一个 IB 定义了一组面，它对应的顶点数据在 <code>vb</code> 文件里。</p><h3 id="缓冲槽文件" tabindex="-1">缓冲槽文件 <a class="header-anchor" href="#缓冲槽文件" aria-label="Permalink to &quot;缓冲槽文件&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>000038-ib=7ad7e69e-vb0-layout=5bfd1268-topology=trianglelist-stride=40-count=18531.buf</span></span>
<span class="line"><span>000038-ib=7ad7e69e-vs-cb4=ad3c80a5.buf</span></span>
<span class="line"><span>000041-ps-t0=10c4fa9f.dds</span></span>
<span class="line"><span>000041-ps-t3=b0e08915.dds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><table tabindex="0"><thead><tr><th>标记</th><th>含义</th></tr></thead><tbody><tr><td><code>vb0</code> <code>vb1</code> <code>vb2</code> …</td><td>顶点缓冲槽位（InputSlot 0/1/2…）</td></tr><tr><td><code>vs-cb0</code> … <code>vs-cb4</code></td><td>Vertex Shader 常量缓冲槽</td></tr><tr><td><code>vs-t0</code> … <code>vs-t8</code></td><td>Vertex Shader 纹理/SRV 槽（骨骼矩阵经常在这里）</td></tr><tr><td><code>ps-t0</code> … <code>ps-t4</code></td><td>Pixel Shader 纹理槽（<strong>贴图都在这里</strong>）</td></tr><tr><td><code>cs-t0</code> … <code>cs-t4</code></td><td>Compute Shader 槽（形态键、GPU 蒙皮输出常在这里）</td></tr><tr><td><code>o0</code> <code>o1</code></td><td>渲染目标（RenderTarget）</td></tr></tbody></table><h3 id="配套的-txt" tabindex="-1">配套的 <code>.txt</code> <a class="header-anchor" href="#配套的-txt" aria-label="Permalink to &quot;配套的 \`.txt\`&quot;">​</a></h3><p><code>.buf</code> 是纯二进制，<code>.txt</code> 是 3DMigoto 顺手导出的<strong>人类可读说明</strong>。对于 <code>vb</code> 和 <code>ib</code>，这个 <code>.txt</code> 极其重要 —— 它是唯一告诉你「数据怎么解读」的地方。</p><p>VB 的 <code>.txt</code> 长这样：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stride: 40</span></span>
<span class="line"><span>first vertex: 0</span></span>
<span class="line"><span>vertex count: 18531</span></span>
<span class="line"><span>topology: trianglelist</span></span>
<span class="line"><span>element[0]:</span></span>
<span class="line"><span>  SemanticName: POSITION</span></span>
<span class="line"><span>  SemanticIndex: 0</span></span>
<span class="line"><span>  Format: DXGI_FORMAT_R32G32B32_FLOAT</span></span>
<span class="line"><span>  InputSlot: 0</span></span>
<span class="line"><span>  AlignedByteOffset: 0</span></span>
<span class="line"><span>  InputSlotClass: per-vertex</span></span>
<span class="line"><span>  InstanceDataStepRate: 0</span></span>
<span class="line"><span>element[1]:</span></span>
<span class="line"><span>  SemanticName: NORMAL</span></span>
<span class="line"><span>  SemanticIndex: 0</span></span>
<span class="line"><span>  Format: DXGI_FORMAT_R32G32B32_FLOAT</span></span>
<span class="line"><span>  InputSlot: 0</span></span>
<span class="line"><span>  AlignedByteOffset: 12</span></span>
<span class="line"><span>  InputSlotClass: per-vertex</span></span>
<span class="line"><span>  InstanceDataStepRate: 0</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>vertex-data:</span></span>
<span class="line"><span>  vb0[0]: -0.529101 -0.042439 0.055176 -0.572331 -0.784331 0.239293</span></span>
<span class="line"><span>  vb0[1]: -0.530645 -0.041132 0.055768 -0.553479 -0.792604 0.249178</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>三个关键区块：</p><ol><li><strong>header</strong>（<code>stride</code> / <code>first vertex</code> / <code>vertex count</code> / <code>topology</code>）</li><li><strong>element 列表</strong>（字段名、格式、槽位、字节偏移）</li><li><strong><code>vertex-data</code> 预览</strong>（前几个顶点的<strong>实际数值</strong>）</li></ol><div class="tip custom-block"><p class="custom-block-title">为什么 <code>vertex-data</code> 是个宝藏</p><p>它是<strong>唯一能反查&quot;我的解读对不对&quot;的锚点</strong>。</p><p>你猜 stride=40，那就按 40 切，看第 0 个顶点的前 12 字节是不是 -0.529101 / -0.042439 / 0.055176。对上了，布局就确认了。对不上，换个数再试。</p><p>后面<a href="/SSMT4-Tutorial/guide/extract/layout#拿-vertex-data-反查-stride">验证 stride</a>会详细讲。</p></div><p>IB 的 <code>.txt</code> 长这样：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>topology: trianglelist</span></span>
<span class="line"><span>format: DXGI_FORMAT_R16_UINT</span></span>
<span class="line"><span>first index: 59307</span></span>
<span class="line"><span>index count: 10446</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>0 1 2</span></span>
<span class="line"><span>2 1 3</span></span>
<span class="line"><span>3 1 4</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>后面每行三个数字就是一个三角形（三个顶点索引）。</p><h2 id="log-txt-是什么" tabindex="-1"><code>log.txt</code> 是什么 <a class="header-anchor" href="#log-txt-是什么" aria-label="Permalink to &quot;\`log.txt\` 是什么&quot;">​</a></h2><p>它是这次帧里<strong>所有 dx11 调用的流水账</strong>，几 MB 到几十 MB。对提取来说，它提供三样东西：</p><h3 id="_1-资源哈希-→-真实文件路径" tabindex="-1">1. 资源哈希 → 真实文件路径 <a class="header-anchor" href="#_1-资源哈希-→-真实文件路径" aria-label="Permalink to &quot;1. 资源哈希 → 真实文件路径&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>000007 Dumping Buffer 1844db3b -&gt; 9c2ac78e.buf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><details class="details custom-block"><summary>为什么需要这一层</summary><p>因为 <code>Dumping Buffer</code> 是 3Dmigoto 决定「要不要保存这个资源」时打的日志。同一个 GPU 缓冲可能被多个 draw 帧内反复改写，内容一样就只存一份（deduped），名字取内容哈希。所以逻辑名和文件名对不上。</p><p>平铺形态下也有这层日志（只是文件名恰好保留了资源名），所以<strong>统一都从 log 查最稳</strong>。</p></details><h3 id="_2-drawcall-的绘制参数" tabindex="-1">2. drawcall 的绘制参数 <a class="header-anchor" href="#_2-drawcall-的绘制参数" aria-label="Permalink to &quot;2. drawcall 的绘制参数&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>000038 DrawIndexed(IndexCount:10446, StartIndexLocation:59307, BaseVertexLocation:0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这三个数决定「这个 draw 从 IB 的哪一段画多少个三角形」：</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th><th>单位</th></tr></thead><tbody><tr><td><code>IndexCount</code></td><td>画多少个索引</td><td>索引个数（三角形数 = 这个 / 3）</td></tr><tr><td><code>StartIndexLocation</code></td><td>从第几个索引开始</td><td><strong>索引个数</strong>，不是字节</td></tr><tr><td><code>BaseVertexLocation</code></td><td>顶点索引的基础偏移</td><td><strong>顶点个数</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>BaseVertexLocation</code> 是最容易漏的一项</p><p>很多游戏把大量模型塞进一个巨大的 VB 池，靠 <code>BaseVertexLocation</code> 指向自己那一段。它非 0 而你忘了加，模型就会炸成一片乱飞的尖刺 —— 而所有&quot;顶点数校验&quot;&quot;布局校验&quot;都会通过。</p><p>见<a href="/SSMT4-Tutorial/guide/extract/vertices#坑漏了-basevertexlocation">坑：漏了 BaseVertexLocation</a>。</p></div><h3 id="_3-顶点缓冲的绑定关系" tabindex="-1">3. 顶点缓冲的绑定关系 <a class="header-anchor" href="#_3-顶点缓冲的绑定关系" aria-label="Permalink to &quot;3. 顶点缓冲的绑定关系&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>000038 IASetVertexBuffers(StartSlot:0, NumBuffers:2, ...)</span></span>
<span class="line"><span>  Src: resource=0x0000000a1b2c3d4e hash=1844db3b</span></span>
<span class="line"><span>  Src: resource=0x0000000a1b2c3d5f hash=9798ab34</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>告诉你这次 draw 读了哪些 VB，以及槽位顺序。找 GPU 预蒙皮的「配对 draw」时要用它。</p><h2 id="一个真实目录的规模" tabindex="-1">一个真实目录的规模 <a class="header-anchor" href="#一个真实目录的规模" aria-label="Permalink to &quot;一个真实目录的规模&quot;">​</a></h2><p>拿实战案例的转储举例：</p><table tabindex="0"><thead><tr><th>项</th><th>数量</th></tr></thead><tbody><tr><td>根目录条目</td><td>8078（其中 8076 个 <code>.lnk</code>）</td></tr><tr><td><code>deduped\\</code> 真实文件</td><td>974（446 <code>.txt</code> / 285 <code>.dds</code> / 243 <code>.buf</code>）</td></tr><tr><td>总大小</td><td>1.49 GB</td></tr><tr><td><code>log.txt</code> 大小</td><td>4.8 MB</td></tr><tr><td><code>Dumping Buffer</code> 映射条数</td><td>6462</td></tr><tr><td>里面包含的 IB 数量</td><td>235 个 trianglelist + 8 个 pointlist</td></tr></tbody></table><p>一个模型只有几千个三角形，但转储里有 235 个 IB —— 大部分是别的角色、地形、UI。所以<a href="/SSMT4-Tutorial/guide/dump/find-ib">锁定目标 IB</a>是必要的一步，不能瞎猜。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>→ <a href="/SSMT4-Tutorial/guide/dump/capture">抓取一次转储</a>：怎么让 3DMigoto 把想要的东西都 dump 下来</p><p>或者直接跳到 → <a href="/SSMT4-Tutorial/guide/dump/find-ib">锁定目标 IB</a>：如果你的转储已经在了</p>`,51)])])}const h=s(p,[["render",d]]);export{u as __pageData,h as default};
